package com.aurasound.next;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.MediaSession;import android.media.session.PlaybackState;import android.media.MediaMetadata;import android.net.Uri;import android.os.*;import org.json.*;
public class PlaybackService extends Service{
 public static final String ACTION_SET_QUEUE="com.aurasound.next.SET_QUEUE",ACTION_TOGGLE="com.aurasound.next.TOGGLE",ACTION_NEXT="com.aurasound.next.NEXT",ACTION_PREVIOUS="com.aurasound.next.PREVIOUS",ACTION_STATE="com.aurasound.next.STATE";
 private static final String CHANNEL="aurasound_playback";private static final int NOTIFICATION=77;private MediaPlayer player;private MediaSession session;private final java.util.ArrayList<Track> queue=new java.util.ArrayList<>();private int index=-1;private boolean wantsPlay=false;
 private static class Track{String uri,title,artist;Track(String u,String t,String a){uri=u;title=t;artist=a;}}
 @Override public void onCreate(){super.onCreate();createChannel();session=new MediaSession(this,"AuraSoundSession");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){play();}@Override public void onPause(){pause();}@Override public void onSkipToNext(){next(1);}@Override public void onSkipToPrevious(){next(-1);}@Override public void onStop(){pause();stopForeground(true);}});session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setActive(true);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_STICKY;String a=intent.getAction();if(ACTION_SET_QUEUE.equals(a))loadQueue(intent.getStringExtra("queue"),intent.getIntExtra("index",0),intent.getBooleanExtra("autoplay",true));else if(ACTION_TOGGLE.equals(a)){if(player!=null&&player.isPlaying())pause();else play();}else if(ACTION_NEXT.equals(a))next(1);else if(ACTION_PREVIOUS.equals(a))next(-1);return START_STICKY;}
 private void loadQueue(String json,int selected,boolean autoplay){queue.clear();try{JSONArray a=new JSONArray(json);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String u=o.optString("url");if(u.startsWith("content:"))queue.add(new Track(u,o.optString("name","آهنگ"),o.optString("artist",o.optString("album",""))));}}catch(Exception ignored){}if(queue.isEmpty()){stopSelf();return;}index=Math.max(0,Math.min(selected,queue.size()-1));wantsPlay=autoplay;startForeground(NOTIFICATION,notification());prepare();}
 private void prepare(){releasePlayer();if(index<0||index>=queue.size())return;Track t=queue.get(index);player=new MediaPlayer();try{player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(this,Uri.parse(t.uri));player.setOnPreparedListener(mp->{if(wantsPlay){mp.start();updateSession(PlaybackState.STATE_PLAYING);}else updateSession(PlaybackState.STATE_PAUSED);publish();});player.setOnCompletionListener(mp->next(1));player.setOnErrorListener((mp,w,e)->{publish();return true;});player.prepareAsync();updateMetadata();publish();}catch(Exception e){publish();}}
 private void play(){if(player==null){if(!queue.isEmpty())prepare();return;}wantsPlay=true;try{if(!player.isPlaying())player.start();updateSession(PlaybackState.STATE_PLAYING);publish();}catch(Exception ignored){}}
 private void pause(){wantsPlay=false;try{if(player!=null&&player.isPlaying())player.pause();}catch(Exception ignored){}updateSession(PlaybackState.STATE_PAUSED);publish();}
 private void next(int d){if(queue.isEmpty())return;index=(index+d+queue.size())%queue.size();wantsPlay=true;prepare();}
 private void updateMetadata(){if(session==null||queue.isEmpty())return;Track t=queue.get(index);long duration=0;try{if(player!=null)duration=player.getDuration();}catch(Exception ignored){}session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,t.title).putString(MediaMetadata.METADATA_KEY_ARTIST,t.artist).putLong(MediaMetadata.METADATA_KEY_DURATION,duration).build());}
 private void updateSession(int state){if(session==null)return;long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_STOP;long pos=0;try{if(player!=null)pos=player.getCurrentPosition();}catch(Exception ignored){}session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(state,pos,state==PlaybackState.STATE_PLAYING?1:0).build());}
 private void publish(){if(queue.isEmpty())return;Track t=queue.get(index);Intent i=new Intent(ACTION_STATE).setPackage(getPackageName()).putExtra("index",index).putExtra("playing",player!=null&&player.isPlaying()).putExtra("title",t.title).putExtra("artist",t.artist);sendBroadcast(i);updateMetadata();updateSession(player!=null&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTIFICATION,notification());}
 private Notification notification(){Track t=queue.isEmpty()?new Track("","","AuraSound"):queue.get(Math.max(0,Math.min(index,queue.size()-1)));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);boolean p=player!=null&&player.isPlaying();Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(t.title).setContentText(t.artist).setContentIntent(open).setOngoing(p).setVisibility(Notification.VISIBILITY_PUBLIC).addAction(action(android.R.drawable.ic_media_previous,"قبلی",ACTION_PREVIOUS,1)).addAction(action(p?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,p?"مکث":"پخش",ACTION_TOGGLE,2)).addAction(action(android.R.drawable.ic_media_next,"بعدی",ACTION_NEXT,3));if(Build.VERSION.SDK_INT>=21)b.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return b.build();}
 private Notification.Action action(int icon,String title,String action,int id){PendingIntent pi=PendingIntent.getService(this,id,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Action.Builder(icon,title,pi).build();}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"پخش موسیقی",NotificationManager.IMPORTANCE_LOW);c.setDescription("کنترل پخش موسیقی AuraSound");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
 private void releasePlayer(){if(player!=null){try{player.reset();player.release();}catch(Exception ignored){}player=null;}}
 @Override public void onDestroy(){releasePlayer();if(session!=null){session.setActive(false);session.release();}super.onDestroy();}
 @Override public android.os.IBinder onBind(Intent i){return null;}
}